// @iasiv5/dsh-skills: registers the iasiv5 skill collection with the host
// skill registry as bundled skills (rank 600). Pure host plugin: no client
// bundle, no routes. The skill catalog comes from skills-manifest.json
// (generated by scripts/build.mjs, invocation precomputed from SKILL.md
// frontmatter with the same semantics as the host's parseInvocationPolicy);
// bodies are read on demand from skills/<dir>/SKILL.md.
import { readFileSync } from "node:fs";
import { join, sep } from "node:path";
import { fileURLToPath } from "node:url";

const name = "iasi-skills";
const inject = ["skills"];

const PROVIDER_NAME = "@iasiv5/dsh-skills";
const BUNDLED_SKILL_RANK = 600;
const packageRoot = fileURLToPath(new URL("../", import.meta.url));
const FRONTMATTER_RE = /^---\r?\n[\s\S]*?\r?\n---(?:\r?\n|$)/u;

function toPosix(path) {
  return path.split(sep).join("/");
}

function readManifest(base) {
  const manifestPath = join(base, "skills-manifest.json");
  let parsed;
  try {
    parsed = JSON.parse(readFileSync(manifestPath, { encoding: "utf8" }));
  } catch (error) {
    throw new Error(`${PROVIDER_NAME}: cannot read skills-manifest.json at ${manifestPath}: ${error.message}`);
  }
  if (!parsed || !Array.isArray(parsed.skills)) {
    throw new Error(`${PROVIDER_NAME}: skills-manifest.json is malformed (expected {"skills": [...]})`);
  }
  return parsed.skills;
}

function candidateFor(base, skill) {
  const directory = toPosix(join(base, "skills", skill.dir));
  return {
    name: skill.name,
    description: skill.description,
    ...(skill.whenToUse !== undefined ? { whenToUse: skill.whenToUse } : {}),
    invocation: {
      modelInvocable: skill.invocation?.modelInvocable ?? true,
      userInvocable: skill.invocation?.userInvocable ?? true
    },
    provider: PROVIDER_NAME,
    source: "bundled",
    rank: BUNDLED_SKILL_RANK,
    path: `${directory}/SKILL.md`,
    resourceBase: { kind: "directory", path: directory }
  };
}

function apply(ctx, config = {}) {
  const base = config.manifestDir ?? packageRoot;
  const entries = readManifest(base);

  const provider = {
    name: PROVIDER_NAME,
    list: async () => entries.map((skill) => candidateFor(base, skill)),
    async get(candidate, options) {
      const { readFile } = await import("node:fs/promises");
      const raw = await readFile(candidate.path, { encoding: "utf8", signal: options?.signal });
      const match = FRONTMATTER_RE.exec(raw);
      if (match === null) {
        throw new Error(`${PROVIDER_NAME}: ${candidate.path} has no YAML frontmatter`);
      }
      return {
        name: candidate.name,
        description: candidate.description,
        ...(candidate.whenToUse !== undefined ? { whenToUse: candidate.whenToUse } : {}),
        invocation: candidate.invocation,
        provider: candidate.provider,
        source: candidate.source,
        resourceBase: candidate.resourceBase,
        path: candidate.path,
        content: raw.slice(match[0].length).trim()
      };
    }
  };

  ctx.skills.registerProvider(() => provider);
}

export { name, inject, apply };
